        return []

    # Find all unique values in the grid
    unique = set()
    for row in grid:
        for val in row:
            unique.add(val)

    # Find the value that is not 5
    other_val = None
    for v in unique:
        if v != 5:
            other_val = v
            break

    # If no other value exists, return grid of zeros
    if other_val is None:
        return [[0 for _ in row] for row in grid]

    # Transform: cells with 5 become other_val, all others become 0
